const String _boundary =
    'ReLoop records contractual allocations and independent NGO reviews. EPR certificates are generated by registered processors on the CPCB portal, and your organisation files its own returns there. Targets shown are the values you entered, not statutory obligations computed by ReLoop.';

/// One allocation → run → source batch line. A batch's share of an allocation is pro rata by its output share,
/// with run output = sum of apportioned output across the run's batches.
class LineageRow {
  final J allocation;
  final String batchCode;
  final String recordCode;
  final double shareKg;
  final String? decision;
  final String? locality;
  const LineageRow(this.allocation, this.batchCode, this.recordCode, this.shareKg, this.decision, this.locality);
}

class Lineage {
  final List<LineageRow> rows;
  final bool loading;
  final ApiError? error;
  final List<J>? allocations;
  final VoidCallback refetch;
  const Lineage(this.rows, this.loading, this.error, this.allocations, this.refetch);
  List<J> get allocs => allocations ?? const [];
}

({double verified, double concern, double pending}) split(Iterable<LineageRow> rows) {
  double v = 0, c = 0, p = 0;
  for (final r in rows) {
    if (r.decision == 'VERIFIED') {
      v += r.shareKg;
    } else if (['FLAGGED', 'REJECTED', 'REQUIRES_CORRECTION'].contains(r.decision)) {
      c += r.shareKg;
    } else {
      p += r.shareKg;
    }
  }
  return (verified: v, concern: c, pending: p);
}

/// EPR users cannot read processing records directly; each passport lists the runs a batch fed and the
/// allocation ids (theirs only) on those runs. Lineage is assembled from those passports.
class LineageBuilder extends StatelessWidget {
  final Widget Function(BuildContext context, Lineage lin) builder;
  const LineageBuilder({super.key, required this.builder});

  @override
  Widget build(BuildContext context) => Queries(
        queries: {'a': QDef(K.allocations, Api.allocations), 'b': QDef(K.batchList('PROCESSED'), () => Api.batches(status: 'PROCESSED'))},
        builder: (context, q) {
          final err = q.error('a') ?? q.error('b');
          if (!q.has('a') || !q.has('b')) return builder(context, Lineage(const [], err == null, err, q.get<List<J>>('a'), q.refetch));
          final codes = q.list('b').map(bcode).where((c) => c.isNotEmpty).toList();
          return Queries(
            queries: {for (final c in codes) c: QDef(K.passport(c), () => Api.passport(c))},
            builder: (context, pq) {
              final loading = codes.any((c) => pq.pending(c));
              final perr = codes.map((c) => pq.error(c)).whereType<ApiError>().firstOrNull;
              if (loading || perr != null) return builder(context, Lineage(const [], loading, perr, q.list('a'), q.refetch));
              final passports = [for (final c in codes) pq.get<J>(c)].whereType<J>().toList();
              final runOut = <String, double>{};
              for (final p in passports) {
                for (final r in jl(jo(p['custody'])?['processing_runs'])) {
                  final k = sn(r['record_code']) ?? '';
                  runOut[k] = (runOut[k] ?? 0) + (dn(r['apportioned_output_kg']) ?? 0);
                }
              }
              final rows = <LineageRow>[];
              for (final a in q.list('a').where((x) => x['status'] == 'ACTIVE')) {
                for (final p in passports) {
                  if (!jl(p['epr_allocations']).any((e) => e['allocation_id'] == a['id'])) continue;
                  final cur = jl(p['verifications']).where((v) => v['is_current'] == true).firstOrNull;
                  for (final r in jl(jo(p['custody'])?['processing_runs'])) {
                    final total = runOut[sn(r['record_code'])] ?? 0;
                    if (total == 0) continue;
                    rows.add(LineageRow(a, sn(p['batch_code']) ?? '', sn(r['record_code']) ?? '', (dn(a['quantity_kg']) ?? 0) * (dn(r['apportioned_output_kg']) ?? 0) / total,
                        sn(cur?['decision']), sn(jo(p['generator'])?['locality'])));
                  }
                }
              }
              return builder(context, Lineage(rows, false, null, q.list('a'), q.refetch));
            },
          );
        },
      );
}

typedef _Sum = ({String cat, double? target, double allocated, ({double verified, double concern, double pending}) s});

List<String> _periods(Iterable<String> extra) => {currentReportingPeriod(), ...extra}.toList();
String _short(dynamic id) => (sn(id) ?? '').padRight(8).substring(0, 8);

Widget _allocStatus(J a) => a['reverses_allocation_id'] != null
    ? const Pill('Reversal entry', tone: Tone.warn)
    : (a['status'] == 'ACTIVE' ? const Pill('Active', tone: Tone.ok) : const Pill('Reversed'));

/* ─────────────── Overview ─────────────── */
class EprOverview extends StatefulWidget {
  const EprOverview({super.key});
  @override
  State<EprOverview> createState() => _EprOverviewState();
}

class _EprOverviewState extends State<EprOverview> {
  String _period = currentReportingPeriod();
  @override
  Widget build(BuildContext context) {
    final c = context.c;
    return Queries(
      queries: {'d': QDef(K.eprDash(_period), () => Api.eprDashboard(_period)), 't': QDef(K.targets, Api.targets), 'x': QDef(K.eprDisc, Api.eprDiscrepancies)},
      builder: (context, q) => LineageBuilder(
        builder: (context, lin) {
          final periods = _periods(q.list('t').map((t) => sn(t['reporting_period']) ?? ''));
          return Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
            PageHeader(
              title: 'Compliance overview',
              description: 'Recycling quantities attributed to your organisation against your self-declared targets, split by independent verification status.',
              actions: [
                SizedBox(width: 150, child: Sel<String>(value: _period, items: [for (final p in periods) (p, p)], onChanged: (v) => setState(() => _period = v ?? _period))),
                Btn('Reports', icon: Icons.download_outlined, kind: BtnKind.outline, onPressed: () => go('/e/reports')),
              ],
            ),
            const Note(tone: Tone.warn, title: 'Scope', text: _boundary),
            const SizedBox(height: 16),
            qView<J>(q, 'd', (d) {
              final rows = lin.rows.where((r) => r.allocation['reporting_period'] == _period).toList();
              final s = split(rows);
              final openDisc = q.list('x').where((x) => x['status'] == 'OPEN').length;
              final target = dn(d['total_target_kg']) ?? 0;
              final cats = jl(d['targets_by_category']);
              return Gap([
                KpiGrid([
                  Kpi(
                      icon: Icons.link,
                      label: 'Allocated to you',
                      value: kg(dn(d['total_allocated_kg'])),
                      sub: target != 0 ? '${pct(dn(d['compliance_pct']))} of ${kg(target)} self-declared' : 'No targets set for this period'),
                  Kpi(icon: Icons.verified_user_outlined, label: 'From NGO-verified batches', value: lin.loading ? '…' : kg(s.verified), sub: 'Computed per source batch'),
                  Kpi(label: 'Awaiting NGO review', value: lin.loading ? '…' : kg(s.pending), sub: 'Allocated, not yet verified'),
                  Kpi(icon: Icons.warning_amber_rounded, label: 'Linked to flagged evidence', value: lin.loading ? '…' : kg(s.concern), sub: '$openDisc open discrepancy flag${openDisc == 1 ? '' : 's'}'),
                ]),
                if (s.concern > 0)
                  Note(
                    tone: Tone.bad,
                    child: Wrap(spacing: 6, children: [
                      Text('${kg(s.concern)} allocated to you comes from batches an NGO flagged, rejected or sent back for correction. Review before relying on it.'),
                      LinkText('Open discrepancies', () => go('/e/discrepancies')),
                    ]),
                  ),
                if (!lin.loading && ((dn(d['verified_allocated_kg']) ?? 0) - s.verified).abs() > 0.5)
                  Note(
                      text:
                          "The backend's own dashboard reports ${kg(dn(d['verified_allocated_kg']))} as verified because it counts a whole allocation once any source batch is verified. The figure above attributes each allocation to its source batches and counts only the verified share."),
                Panel(
                  title: 'Progress by packaging category',
                  sub: 'kg · bar length = your target',
                  footer: SourceLine('ReLoop API · /epr/dashboard, /epr/allocations, /passports', period: _period),
                  child: cats.isEmpty
                      ? EmptyState(title: 'No targets for this period', action: Btn('Set targets', icon: Icons.track_changes, small: true, onPressed: () => go('/e/obligations')))
                      : Gap([
                          for (final t in cats)
                            () {
                              final cat = sn(t['category']);
                              final tk = dn(t['target_kg']) ?? 0;
                              final cs = split(rows.where((r) => r.allocation['packaging_category'] == cat));
                              final al = lin.allocs
                                  .where((a) => a['status'] == 'ACTIVE' && a['reporting_period'] == _period && a['packaging_category'] == cat)
                                  .fold<double>(0, (x, a) => x + (dn(a['quantity_kg']) ?? 0));
                              final bar = SegBar([(cs.verified, c.c1), (cs.pending, c.c3), (cs.concern, c.c5)], tk);
                              final label = Text(categoryLabel(cat), style: TextStyle(fontSize: 12.5, color: c.fg2));
                              final value = numText('${num1(al)} / ${num1(tk)} kg');
                              return context.phone
                                  ? Gap([Row(children: [Expanded(child: label), value]), bar], gap: 4)
                                  : Row(children: [SizedBox(width: 140, child: label), Expanded(child: bar), SizedBox(width: 160, child: value)]);
                            }(),
                          Wrap(spacing: 16, runSpacing: 4, children: [
                            Legend('NGO-verified', c.c1),
                            Legend('Awaiting review', c.c3),
                            Legend('Flagged / rejected', c.c5),
                            Legend('Remaining to target', c.surface2, outlined: true),
                          ]),
                          if (lin.error != null) ErrorState(error: lin.error!, onRetry: lin.refetch),
                        ], gap: 12),
                ),
              ]);
            }),
          ]);
        },
      ),
    );
  }
}

/* ─────────────── Obligations & targets ─────────────── */
class EprObligations extends StatelessWidget {
  const EprObligations({super.key});
  @override
  Widget build(BuildContext context) => Queries(
        queries: {'t': QDef(K.targets, Api.targets), 'a': QDef(K.allocations, Api.allocations)},
        builder: (context, q) {
          double allocated(dynamic p, dynamic cat) => q
              .list('a')
              .where((a) => a['status'] == 'ACTIVE' && a['reporting_period'] == p && a['packaging_category'] == cat)
              .fold<double>(0, (s, a) => s + (dn(a['quantity_kg']) ?? 0));
          void edit(J? t) => showSheet(context, _TargetSheet(t));
          return Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
            PageHeader(
              title: 'Obligations & targets',
              description: 'Your self-declared recycling targets by reporting period and packaging category. ReLoop stores what you enter; it does not compute statutory obligations.',
              actions: [Btn('Add or update target', icon: Icons.track_changes, onPressed: () => edit(null))],
            ),
            Panel(
              flush: true,
              footer: const SourceLine('ReLoop API · /epr/targets, /epr/allocations'),
              child: qView<List<J>>(
                q,
                't',
                (ts) => DataList<J>(
                  label: 'Targets',
                  rows: ts,
                  rowKey: (t) => sn(t['id'])!,
                  onTap: edit,
                  emptyTitle: 'No targets yet',
                  cols: [
                    tcol<J>('p', 'Period', (t) => sn(t['reporting_period']) ?? ''),
                    tcol<J>('c', 'Category', (t) => categoryLabel(t['packaging_category']), sortable: false),
                    ncol<J>('t', 'Target', (t) => dn(t['target_kg']), num1),
                    ncol<J>('a', 'Allocated', (t) => allocated(t['reporting_period'], t['packaging_category']), num1, sortable: false),
                    Col<J>('r', 'Remaining', (t) {
                      final rem = (dn(t['target_kg']) ?? 0) - allocated(t['reporting_period'], t['packaging_category']);
                      return numText(num1(rem < 0 ? 0 : rem), bold: true);
                    }, numeric: true),
                    ncol<J>('cv', 'Coverage', (t) {
                      final tk = dn(t['target_kg']) ?? 0;
                      return tk == 0 ? null : allocated(t['reporting_period'], t['packaging_category']) / tk * 100;
                    }, pct, sortable: false),
                    Col<J>('n', 'Source note', (t) => Small(sn(t['source_note']) ?? '—')),
                  ],
                ),
              ),
            ),
            const SizedBox(height: 16),
            const Note(
                text:
                    'Statutory targets depend on your CPCB registration, packaging placed on the market and the current EPR Guidelines for Plastic Packaging. Confirm figures with your compliance adviser.'),
          ]);
        },
      );
}

class _TargetSheet extends StatefulWidget {
  final J? t;
  const _TargetSheet(this.t);
  @override
  State<_TargetSheet> createState() => _TargetSheetState();
}

class _TargetSheetState extends State<_TargetSheet> {
  late final _period = TextEditingController(text: sn(widget.t?['reporting_period']) ?? currentReportingPeriod());
  late String _cat = sn(widget.t?['packaging_category']) ?? 'CAT_I';
  late final _kg = TextEditingController(text: widget.t == null ? '' : '${dn(widget.t!['target_kg']) ?? ''}');
  late final _note = TextEditingController(text: sn(widget.t?['source_note']) ?? '');
  Map<String, String> _e = {};
  ApiError? _err;
  bool _busy = false;

  @override
  void dispose() {
    _period.dispose();
    _kg.dispose();
    _note.dispose();
    super.dispose();
  }

  Future<void> _save() async {
    final e = <String, String>{};
    if (!RegExp(r'^FY\d{4}-\d{2}$').hasMatch(_period.text.trim())) e['p'] = 'Format FY2026-27';
    final k = kgError(_kg.text, label: 'Target');
    if (k != null) e['k'] = k;
    if (_note.text.length > 300) e['n'] = 'At most 300 characters';
    setState(() => _e = e);
    if (e.isNotEmpty) return;
    setState(() {
      _busy = true;
      _err = null;
    });
    final r = await mutate(
      () => Api.upsertTarget({
        'reporting_period': _period.text.trim(),
        'packaging_category': _cat,
        'target_kg': double.parse(_kg.text.trim()),
        if (_note.text.trim().isNotEmpty) 'source_note': _note.text.trim(),
      }),
      invalidate: [K.targets, K.epr],
      success: (_) => 'Target saved',
      onError: (e) => _err = e,
    );
    if (!mounted) return;
    setState(() => _busy = false);
    if (r != null) Navigator.pop(context);
  }

  @override
  Widget build(BuildContext context) => SheetScaffold(
        title: 'Self-declared target',
        description: 'Saving a target for an existing period and category replaces it.',
        actions: [Btn('Cancel', kind: BtnKind.outline, onPressed: () => Navigator.pop(context)), Btn('Save target', loading: _busy, onPressed: _save)],
        children: [
          RGrid(minWidth: 220, maxCols: 2, gap: 16, children: [
            Field(label: 'Reporting period', required: true, error: _e['p'], child: In(_period, hasError: _e['p'] != null)),
            Field(label: 'Category', child: Sel<String>(value: _cat, items: kCategoryLabel.entries.map((e) => (e.key, e.value)).toList(), onChanged: (v) => setState(() => _cat = v ?? 'CAT_I'))),
            Field(label: 'Target (kg)', required: true, error: _e['k'], child: In(_kg, decimal: true, hasError: _e['k'] != null)),
            Field(label: 'Source note', error: _e['n'], child: In(_note, placeholder: 'e.g. FY26 EPR plan v2')),
          ]),
          if (_err != null) Note(tone: Tone.bad, text: _err!.message),
        ],
      );
}

