/* ─────────────── Traceability ─────────────── */
class EprTrace extends StatefulWidget {
  const EprTrace({super.key});
  @override
  State<EprTrace> createState() => _EprTraceState();
}

class _EprTraceState extends State<EprTrace> {
  String? _sel;
  @override
  Widget build(BuildContext context) {
    final c = context.c;
    return LineageBuilder(
      builder: (context, lin) {
        final active = lin.allocs.where((a) => a['status'] == 'ACTIVE').toList();
        final cur = _sel ?? sn(active.firstOrNull?['id']);
        final rows = lin.rows.where((r) => r.allocation['id'] == cur).toList();
        final a = active.where((x) => x['id'] == cur).firstOrNull;
        Widget box(String label, Widget value, {List<Widget> trailing = const []}) => Container(
              padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
              decoration: BoxDecoration(border: Border.all(color: c.line), borderRadius: BorderRadius.circular(6)),
              child: Wrap(spacing: 12, runSpacing: 4, crossAxisAlignment: WrapCrossAlignment.center, children: [
                SizedBox(width: 96, child: Text(label.toUpperCase(), style: TextStyle(fontSize: 10.5, letterSpacing: 0.6, color: c.fg3))),
                value,
                ...trailing,
              ]),
            );
        Widget indent(Widget w) => Container(
              margin: const EdgeInsets.only(left: 14),
              padding: const EdgeInsets.only(left: 14),
              decoration: BoxDecoration(border: Border(left: BorderSide(color: c.line2))),
              child: w,
            );
        return Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
          const PageHeader(
              title: 'Batch traceability',
              description: 'Follow any allocation back through its processing run to each source batch. Generator identities are withheld; locality and type are shown.'),
          if (lin.loading)
            const LoadingRows(rows: 6)
          else if (lin.error != null)
            ErrorState(error: lin.error!, onRetry: lin.refetch)
          else if (active.isEmpty)
            const Panel(child: EmptyState(title: 'No active allocations'))
          else
            TwoCol(
              mainFlex: 1,
              sideFlex: 2,
              main: Panel(
                title: 'Allocations',
                flush: true,
                child: Column(children: [
                  for (final x in active)
                    Material(
                      color: x['id'] == cur ? c.accentSoft : Colors.transparent,
                      child: InkWell(
                        onTap: () => setState(() => _sel = sn(x['id'])),
                        child: Container(
                          padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 10),
                          decoration: BoxDecoration(border: Border(bottom: BorderSide(color: c.line))),
                          child: Row(children: [
                            Expanded(
                              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                                Mono(_short(x['id']), size: 12),
                                Small('${x['reporting_period']} · ${categoryLabel(x['packaging_category'])}', size: 11.5),
                              ]),
                            ),
                            numText(kg(dn(x['quantity_kg']))),
                          ]),
                        ),
                      ),
                    ),
                ]),
              ),
              side: a == null
                  ? const SizedBox.shrink()
                  : Panel(
                      title: 'Lineage',
                      sub: '${kg(dn(a['quantity_kg']))} · recorded ${date(a['created_at'])}',
                      child: Gap([
                        box('Allocation', SelectableText(sn(a['id']) ?? '', style: mono(context, size: 12))),
                        for (final code in {for (final r in rows) r.recordCode})
                          indent(Gap([
                            box('Run', Mono(code)),
                            indent(Gap([
                              for (final r in rows.where((r) => r.recordCode == code))
                                box('Source batch', BatchLink(r.batchCode), trailing: [Small(r.locality ?? ''), numText(kg(r.shareKg)), NgoPill(r.decision)]),
                            ], gap: 8)),
                          ], gap: 8)),
                        if (rows.isEmpty) const Note(text: 'No source batches found for this allocation in the processed-batch records available to you.'),
                      ], gap: 8),
                    ),
            ),
        ]);
      },
    );
  }
}

