/* ─────────────── Discrepancies ─────────────── */
class EprDiscrepancies extends StatelessWidget {
  const EprDiscrepancies({super.key});
  @override
  Widget build(BuildContext context) => Queries(
        queries: {'d': QDef(K.eprDisc, Api.eprDiscrepancies), 'b': QDef(K.batchList(), () => Api.batches())},
        builder: (context, q) {
          final m = byId(q.list('b'));
          return Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
            const PageHeader(title: 'Discrepancy monitoring', description: 'Anomaly flags on source batches behind your active allocations.'),
            const Note(text: 'Raising a discrepancy from this workspace is not supported by the backend yet. Contact the recycler or the NGO reviewer directly.'),
            const SizedBox(height: 16),
            Panel(
              flush: true,
              footer: const SourceLine('ReLoop API · /epr/discrepancies'),
              child: qView<List<J>>(
                q,
                'd',
                (ds) => DataList<J>(
                  label: 'Discrepancies',
                  rows: ds,
                  rowKey: (d) => sn(d['flag_id'])!,
                  sortKey: 'd',
                  sortAsc: false,
                  filters: [Flt<J>('s', 'Status', const [('OPEN', 'Open'), ('RESOLVED', 'Resolved')], (d) => sn(d['status']) ?? '')],
                  emptyTitle: 'No discrepancies',
                  emptyBody: 'No anomaly flags are linked to batches behind your allocations.',
                  cols: [
                    Col<J>('d', 'Raised', (d) => Small(dateTime(d['created_at'])), sort: (d) => sn(d['created_at'])),
                    tcol<J>('r', 'Rule', (d) => humanize(d['rule_code'])),
                    Col<J>('v', 'Severity', (d) => Pill(humanize(d['severity']), tone: d['severity'] == 'HIGH' ? Tone.bad : Tone.warn)),
                    Col<J>('b', 'Batch', (d) {
                      final b = m[sn(d['batch_id'])];
                      return b != null ? BatchLink(bcode(b)) : const Text('—');
                    }),
                    Col<J>(
                        'x',
                        'Details',
                        (d) => ConstrainedBox(
                              constraints: const BoxConstraints(maxWidth: 360),
                              child: Small((jo(d['details']) ?? const <String, dynamic>{}).entries.map((e) => '${humanize(e.key)}: ${e.value}').join(' · '), color: context.c.fg2),
                            )),
                    Col<J>('s', 'Status', (d) => d['status'] == 'OPEN' ? const Pill('Open', tone: Tone.bad) : Pill(humanize(d['status']), tone: Tone.ok)),
                  ],
                ),
              ),
            ),
          ]);
        },
      );
}

/* ─────────────── Reports ─────────────── */
class EprReports extends StatefulWidget {
  const EprReports({super.key});
  @override
  State<EprReports> createState() => _EprReportsState();
}

class _EprReportsState extends State<EprReports> {
  String _period = currentReportingPeriod();
  @override
  Widget build(BuildContext context) => Queries(
        queries: {'t': QDef(K.targets, Api.targets), 'c': QDef(K.eprCerts, Api.eprCertificates)},
        builder: (context, q) => LineageBuilder(
          builder: (context, lin) {
            final allocs = lin.allocs.where((a) => a['reporting_period'] == _period).toList();
            final ts = q.list('t').where((t) => t['reporting_period'] == _period).toList();
            final cats = {...ts.map((t) => sn(t['packaging_category']) ?? ''), ...allocs.map((a) => sn(a['packaging_category']) ?? '')}.toList();
            final ready = !lin.loading && lin.error == null && q.has('t');
            final List<_Sum> summary = [
              for (final cat in cats)
                () {
                  final act = allocs.where((a) => a['status'] == 'ACTIVE' && a['packaging_category'] == cat).toList();
                  final ids = act.map((a) => a['id']).toSet();
                  final s = split(lin.rows.where((r) => ids.contains(r.allocation['id'])));
                  return (
                    cat: cat,
                    target: dn(ts.where((t) => t['packaging_category'] == cat).firstOrNull?['target_kg']),
                    allocated: act.fold<double>(0, (x, a) => x + (dn(a['quantity_kg']) ?? 0)),
                    s: s,
                  );
                }(),
            ];
            final linRows = lin.rows.where((r) => r.allocation['reporting_period'] == _period).toList();
            final periods = _periods([...q.list('t').map((t) => sn(t['reporting_period']) ?? ''), ...lin.allocs.map((a) => sn(a['reporting_period']) ?? '')]);
            return Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
              PageHeader(
                title: 'Reports & exports',
                description: 'Compliance summaries built from live ReLoop records for your own records and auditors.',
                actions: [SizedBox(width: 150, child: Sel<String>(value: _period, items: [for (final p in periods) (p, p)], onChanged: (v) => setState(() => _period = v ?? _period)))],
              ),
              const Note(
                  tone: Tone.warn,
                  text:
                      "These exports support, but do not replace, filings on the CPCB EPR portal. The backend's report endpoint does not generate files yet, so exports are produced here from the same API data you see on screen."),
              const SizedBox(height: 16),
              Gap([
                Panel(
                  title: 'Allocation summary · $_period',
                  flush: true,
                  actions: [
                    Btn('CSV',
                        icon: Icons.download_outlined,
                        small: true,
                        kind: BtnKind.outline,
                        onPressed: !ready
                            ? null
                            : () => showCsv(context, 'reloop-epr-summary-$_period.csv', [
                                  ['period', 'category', 'self_declared_target_kg', 'allocated_kg', 'ngo_verified_kg', 'awaiting_review_kg', 'flagged_kg'],
                                  for (final s in summary)
                                    [_period, s.cat, s.target, s.allocated.toStringAsFixed(3), s.s.verified.toStringAsFixed(3), s.s.pending.toStringAsFixed(3), s.s.concern.toStringAsFixed(3)],
                                ])),
                  ],
                  child: !ready
                      ? (lin.error != null ? ErrorState(error: lin.error!, onRetry: lin.refetch) : const LoadingRows())
                      : DataList<_Sum>(
                          label: 'Summary',
                          rows: summary,
                          rowKey: (s) => s.cat,
                          emptyTitle: 'No targets or allocations in this period',
                          cols: [
                            tcol<_Sum>('c', 'Category', (s) => categoryLabel(s.cat), sortable: false),
                            ncol<_Sum>('t', 'Self-declared target', (s) => s.target, num1, sortable: false),
                            ncol<_Sum>('a', 'Allocated', (s) => s.allocated, num1, sortable: false),
                            ncol<_Sum>('v', 'NGO-verified', (s) => s.s.verified, num1, sortable: false),
                            ncol<_Sum>('p', 'Awaiting review', (s) => s.s.pending, num1, sortable: false),
                            ncol<_Sum>('f', 'Flagged', (s) => s.s.concern, num1, sortable: false),
                          ],
                        ),
                ),
                RGrid(minWidth: 320, maxCols: 2, gap: 16, children: [
                  Panel(
                    title: 'Allocation ledger',
                    sub: '${allocs.length} entries in $_period',
                    actions: [
                      Btn('CSV',
                          icon: Icons.download_outlined,
                          small: true,
                          kind: BtnKind.outline,
                          onPressed: allocs.isEmpty
                              ? null
                              : () => showCsv(context, 'reloop-epr-ledger-$_period.csv', [
                                    ['allocation_id', 'recorded_at', 'period', 'category', 'quantity_kg', 'status', 'reverses', 'reason'],
                                    for (final a in allocs)
                                      [a['id'], a['created_at'], a['reporting_period'], a['packaging_category'], a['quantity_kg'], a['status'], a['reverses_allocation_id'], a['reason']],
                                  ])),
                    ],
                    child: KV([
                      KVRow('Active', '${allocs.where((a) => a['status'] == 'ACTIVE').length}'),
                      KVRow('Reversed / reversal entries', '${allocs.where((a) => a['status'] != 'ACTIVE').length}'),
                    ]),
                  ),
                  Panel(
                    title: 'Source-batch lineage',
                    sub: 'Allocation → run → batch with NGO decision',
                    actions: [
                      Btn('CSV',
                          icon: Icons.download_outlined,
                          small: true,
                          kind: BtnKind.outline,
                          onPressed: (!ready || lin.rows.isEmpty)
                              ? null
                              : () => showCsv(context, 'reloop-epr-lineage-$_period.csv', [
                                    ['allocation_id', 'run', 'source_batch', 'attributed_kg', 'ngo_decision'],
                                    for (final r in linRows) [r.allocation['id'], r.recordCode, r.batchCode, r.shareKg.toStringAsFixed(3), r.decision ?? 'NOT_IN_REVIEW'],
                                  ])),
                    ],
                    child: KV([
                      KVRow('Lineage rows', '${linRows.length}'),
                      KVRow('Certificate references', qText<List<J>>(q, 'c', (c) => '${c.length}')),
                    ]),
                  ),
                ]),
              ]),
            ]);
          },
        ),
      );
}
